function EXTRA(R,ICON){
 /* hook: one clean pulse sent, the smeared one received (the worked example's channel 0.2, 1, 0.3) */
 ICON.eqHookPulse=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${EQ_box(0,0,380,160,{st:BLU,sw:3,r:18})}${EQ_T(20,40,'sent: one clean pulse',{fs:26,fw:800,fill:BLU})}${EQ_L(60,136,320,136,EQ_GRY,2)}${[110,190,270].map((sx,i)=>EQ_stem(sx,136,i===1?1:0,80,BLU)).join('')}</g>`;
 ICON.eqHookSmear=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${EQ_box(0,0,380,160,{st:ORG,sw:3,r:18})}${EQ_T(20,40,'received: 0.2 · 1 · 0.3',{fs:26,fw:800,fill:ORG})}${EQ_L(60,136,320,136,EQ_GRY,2)}${[110,190,270].map((sx,i)=>EQ_stem(sx,136,EQ_H[i],80,i===1?BLU:ORG)).join('')}${EQ_T(300,92,'spill',{fs:22,fw:700,fill:EQ_MUT})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.eqZF=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${EQ_L(10,200,170,200,EQ_GRY,2)}${[0,1,2].map(i=>EQ_stem(40+i*50,200,EQ_H[i],130,EQ_GRY)).join('')}${EQ_arrow(180,130,226,130,INK,3)}${EQ_L(230,200,415,200,EQ_GRY,2)}${[0,1,2,3,4].map(i=>EQ_stem(245+i*40,200,EQ_V[i],130,i===2?BLU:ORG)).join('')}${EQ_T(90,252,'before: 0.5',{fs:26,fw:800,a:'middle',fill:EQ_MUT})}${EQ_T(325,252,'after: 0.148',{fs:26,fw:800,a:'middle',fill:BLU})}${EQ_T(210,304,'noise × 1.459',{fs:26,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.eqLMS=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${EQ_T(210,36,`e${EQ_p('2')} after each update`,{fs:26,fw:800,a:'middle'})}${EQ_L(30,250,390,250,EQ_GRY,2)}<rect x="80" y="${250-0.25*720}" width="100" height="${0.25*720}" rx="8" fill="${ORG}"/><rect x="250" y="${(250-0.0099*720).toFixed(1)}" width="100" height="${(0.0099*720).toFixed(1)}" rx="3" fill="${GRN}"/>${EQ_T(130,288,'n = 2: 0.25',{fs:24,fw:800,a:'middle',fill:ORG})}${EQ_T(300,288,'n = 3: 0.0099',{fs:24,fw:800,a:'middle',fill:GRN})}${EQ_arrow(190,150,240,220,INK,3)}</g>`;
 ICON.eqPlane=(x,y)=>{const o=[110,160],k=100;return `<g transform="translate(${x-210} ${y-165})">${EQ_axes(o[0],o[1],k,{l:.6,r:2.9,u:1.5,d:1.5})}${EQ_L(o[0]+k,o[1]-k,o[0]+k,o[1]+k,GRN,4,'stroke-dasharray="8 6"')}${[[0,'s₁'],[-1,'s₂'],[1,'s₃']].map(([d,t])=>EQ_dot(o[0]+k,o[1]+d*k,BLU,10)+EQ_T(o[0]+k+18,o[1]+d*k+9,t,{fs:26,fw:800,fill:BLU})).join('')}${EQ_T(o[0]+k+18,o[1]+58,'d₂₃ = 2',{fs:26,fw:800,fill:GRN})}</g>`};
}
